95	static uint32_t calc_number_of_substrings(uint32_t strlen, uint32_t lb, uint32_t ub) {
96	    // There are len - i + 1 substrings of length i in a length len string.
97	    // Therefore, the total number of substrings with length between lb and ub
98	    // is the sum of the integers inclusive between A = len - ub + 1 and B = len - lb + 1,
99	    // A <= B. This has a closed form: (A + B)(B - A + 1)/2.
100	    if (lb > strlen) {
101	        return 0;
102	    }
103	    uint32_t largest_substr = BSON_MIN(strlen, ub);
104	    uint32_t largest_substr_count = strlen - largest_substr + 1;
105	    uint32_t smallest_substr_count = strlen - lb + 1;
106	    return (largest_substr_count + smallest_substr_count) * (smallest_substr_count - largest_substr_count + 1) / 2;
107	}
