25	mc_utf8_string_with_bad_char_t *mc_utf8_string_with_bad_char_from_buffer(const char *buf, uint32_t len) {
26	    BSON_ASSERT_PARAM(buf);
27	    mc_utf8_string_with_bad_char_t *ret = bson_malloc0(sizeof(mc_utf8_string_with_bad_char_t));
28	    _mongocrypt_buffer_init_size(&ret->buf, len + 1);
29	    memcpy(ret->buf.data, buf, len);
30	    ret->buf.data[len] = BAD_CHAR;
31	    // max # offsets is the total length
32	    ret->codepoint_offsets = bson_malloc0(sizeof(uint32_t) * (len + 1));
33	    const char *cur = buf;
34	    const char *end = buf + len;
35	    ret->codepoint_len = 0;
36	    while (cur < end) {
37	        ret->codepoint_offsets[ret->codepoint_len++] = (uint32_t)(cur - buf);
38	        cur = bson_utf8_next_char(cur);
39	    }
40	    // last codepoint points at the 0xFF at the end of the string
41	    ret->codepoint_offsets[ret->codepoint_len++] = (uint32_t)(end - buf);
42	    // realloc to save some space
43	    ret->codepoint_offsets = bson_realloc(ret->codepoint_offsets, sizeof(uint32_t) * ret->codepoint_len);
44	    return ret;
45	}
