++            }
++            for (uint32_t j = i + 1; j <= len - ss_len; j++) {
++                // Already counted
++                if (idx_is_dupe[j]) {
++                    continue;
++                }
++                uint32_t i_start_byte = str->codepoint_offsets[i];
++                uint32_t i_end_byte = str->codepoint_offsets[i + ss_len];
